CREATE OR REPLACE FUNCTION public.create_product_with_photos(_product jsonb,_oems jsonb,_vehicles jsonb,_supplier_codes jsonb,_initial_stock integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; BEGIN IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Yönetici gerekli'; END IF; pid:=create_admin_product(_product,_oems,_vehicles,_supplier_codes,_initial_stock); UPDATE products SET image_original_url=nullif(_product->>'image_original_url',''), image_thumbnail_url=nullif(_product->>'image_thumbnail_url','') WHERE id=pid; RETURN pid; END $$;
REVOKE ALL ON FUNCTION public.create_product_with_photos(jsonb,jsonb,jsonb,jsonb,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_product_with_photos(jsonb,jsonb,jsonb,jsonb,integer) TO authenticated,service_role;
CREATE POLICY "Validate product photo uploads" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'product-photos' OR ((metadata->>'size')::bigint <= 20971520 AND metadata->>'mimetype' IN ('image/jpeg','image/png','image/webp')));